#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

long long n, c1, c2, answer, power[20], sumArr[10];
vector<long long> buckets[10];

void performQuery(long long p, long long s) {
    for (int i = 0; i <= 6; ++i) {
        long long val = ((s - p * power[i]) % 998244353 + 998244353) % 998244353;
        answer = (answer + val * (long long)buckets[i].size() + sumArr[i]) % 1000000007;
        auto lowerIt = lower_bound(buckets[i].begin(), buckets[i].end(), 998244353 - val);
        answer = (answer - (long long)(buckets[i].end() - lowerIt) * 998244353) % 1000000007;
    }
}

void generateNumbers(long long x, int depth) {
    long long tmp = ((c1++ - x) % 998244353 + 998244353) % 998244353;
    sumArr[depth] = (sumArr[depth] + tmp) % 1000000007;
    buckets[depth].push_back(tmp);
    if (depth == 6) return;
    for (int digit = 0; digit <= 9; ++digit) {
        generateNumbers(x * 10 + digit, depth + 1);
    }
}

void process(long long x) {
    if (x > n) return;
    if ((x + 1) * 1000000LL <= n + 1 && x * 10000000LL > n) {
        performQuery(x, c2);
        c2 += c1;
    } else {
        answer = (answer + ((c2++ - x) % 998244353 + 998244353) % 998244353) % 1000000007;
        for (int i = (x ? 0 : 1); i <= 9; ++i) {
            process(x * 10 + i);
        }
    }
}

int main() {
    cin >> n;
    generateNumbers(0, 0);
    for (int i = 1; i <= 6; ++i) sort(buckets[i].begin(), buckets[i].end());
    power[0] = 1;
    for (int i = 1; i <= 12; ++i) power[i] = power[i - 1] * 10;
    process(0);
    cout << (answer + 1000000007) % 1000000007 << endl;
    return 0;
}
